window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-0e28f34091c0f70e"]={"versions": [{"id": "FIG-0e28f34091c0f70e", "releases": ["R18-10_R4.4.0_R1.5.0", "R19-11", "R20-11", "R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Struktur- und Metamodellübersicht zur Abbildung von Timing-relevanten Elementen in AUTOSAR. Das Diagramm gliedert ein Gesamtsystem hierarchisch in hardwarenahe Ausführungseinheiten (ECU, Cores), Betriebssystem- und Software-Ausführungsentitäten (Interrupts, Tasks, Runnables) sowie Kommunikationsartefakte eines Netzwerks (Frames, PDUs). Es dient als konzeptionelle Basis für die Zeitmodellierung (Timing Extensions / AUTOSAR Timing Analysis) sowohl auf ECU-Ebene als auch auf Bus-Ebene.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>ECU</strong>: Repräsentiert das Steuergerät mit Attributen <code>name</code>, <code>resources</code> und <code>clock</code>.\n</li><li><strong>Hardware-Cores (<code>Core-1</code>, <code>Core-2</code>, ..., <code>Core-n</code>)</strong>: Physische Prozessorkerne innerhalb der ECU mit Attributen <code>name</code> und <code>speed</code>.\n</li><li><strong>Interrupt Mapping (<code>INTERRUPT-1</code> bis <code>INTERRUPT-n</code>)</strong>: Behandlungsroutinen mit Attributen <code>name</code>, <code>prio</code> und <code>scheduling</code>.\n</li><li><strong>Task Mapping (<code>TASK-1</code> bis <code>TASK-n</code>)</strong>: Betriebssystem-Tasks mit Attributen <code>name</code>, <code>prio</code> und <code>scheduling</code>. Jeder Task aggregiert eine geordnete Folge von Software-Komponenten-Runnables (<code>Runnable-1</code>, <code>Runnable-2</code>, ..., <code>Runnable-n</code>).\n</li><li><strong>NETWORK</strong>: Übertragungsmedium mit Attributen <code>type</code>, <code>transmission rate</code> und <code>config.</code>.\n</li><li><strong>FRAME</strong>: Auf dem Netzwerk übertragener Kommunikationsrahmen mit Attributen <code>name</code> und <code>ID (prio)</code>.\n</li><li><strong>PDU (Protocol Data Unit)</strong>: In Frames gemappte Dateneinheiten mit Attributen <code>name</code> und <code>size</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm stellt eine statische Schachtelung und Zuordnungsstruktur dar. Es impliziert jedoch zeitliche Ablaufmechanismen: Runnables werden innerhalb von Tasks sequenziell oder ereignisgesteuert ausgeführt, wobei Scheduling-Strategie und Task-Prioritäten die Zuteilung auf die Cores bestimmen. Analog regeln Interrupt-Prioritäten die Unterbrechung von Tasks. Auf Netzwerkebene werden PDUs in Frames gepackt, deren Sende- und Zugriffszeitpunkte über Frame-ID, Buspriorität und Übertragungsrate determiniert werden.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Für die AUTOSAR-Timing-Modellierung bildet dieses Schema die zentralen Referenzpunkte: <code>ExecutionTime</code> (für Runnables und Tasks auf Cores), <code>LatencyConstraint</code> (zwischen Triggern und Beendigung von Runnables/Tasks), <code>BlockingTime</code> (Ressourcenzugriff) sowie <code>CommunicationCycle</code> bzw. Busverzögerungen (<code>TransmissionTime</code> für PDUs und Frames). Entwickler müssen konsistente Mappings von Runnables zu Tasks, Tasks/Interrupts zu Cores sowie PDUs zu Frames definieren, um deterministische Latenzanalysen (End-to-End Timing Analysis) zu ermöglichen.</p>"}, {"id": "FIG-8374ab7f220ca880", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Struktur- und Metamodellübersicht zur Abbildung von Timing-relevanten Elementen in AUTOSAR. Das Diagramm gliedert ein Gesamtsystem hierarchisch in hardwarenahe Ausführungseinheiten (ECU, Cores), Betriebssystem- und Software-Ausführungsentitäten (Interrupts, Tasks, Runnables) sowie Kommunikationsartefakte eines Netzwerks (Frames, PDUs). Es dient als konzeptionelle Basis für die Zeitmodellierung (Timing Extensions / AUTOSAR Timing Analysis) sowohl auf ECU-Ebene als auch auf Bus-Ebene.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>ECU</strong>: Repräsentiert das Steuergerät mit Attributen <code>name</code>, <code>resources</code> und <code>clock</code>.\n</li><li><strong>Hardware-Cores (<code>Core-1</code>, <code>Core-2</code>, ..., <code>Core-n</code>)</strong>: Physische Prozessorkerne innerhalb der ECU mit Attributen <code>name</code> und <code>speed</code>.\n</li><li><strong>Interrupt Mapping (<code>INTERRUPT-1</code> bis <code>INTERRUPT-n</code>)</strong>: Behandlungsroutinen mit Attributen <code>name</code>, <code>prio</code> und <code>scheduling</code>.\n</li><li><strong>Task Mapping (<code>TASK-1</code> bis <code>TASK-n</code>)</strong>: Betriebssystem-Tasks mit Attributen <code>name</code>, <code>prio</code> und <code>scheduling</code>. Jeder Task aggregiert eine geordnete Folge von Software-Komponenten-Runnables (<code>Runnable-1</code>, <code>Runnable-2</code>, ..., <code>Runnable-n</code>).\n</li><li><strong>NETWORK</strong>: Übertragungsmedium mit Attributen <code>type</code>, <code>transmission rate</code> und <code>config.</code>.\n</li><li><strong>FRAME</strong>: Auf dem Netzwerk übertragener Kommunikationsrahmen mit Attributen <code>name</code> und <code>ID (prio)</code>.\n</li><li><strong>PDU (Protocol Data Unit)</strong>: In Frames gemappte Dateneinheiten mit Attributen <code>name</code> und <code>size</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm stellt eine statische Schachtelung und Zuordnungsstruktur dar. Es impliziert jedoch zeitliche Ablaufmechanismen: Runnables werden innerhalb von Tasks sequenziell oder ereignisgesteuert ausgeführt, wobei Scheduling-Strategie und Task-Prioritäten die Zuteilung auf die Cores bestimmen. Analog regeln Interrupt-Prioritäten die Unterbrechung von Tasks. Auf Netzwerkebene werden PDUs in Frames gepackt, deren Sende- und Zugriffszeitpunkte über Frame-ID, Buspriorität und Übertragungsrate determiniert werden.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Für die AUTOSAR-Timing-Modellierung bildet dieses Schema die zentralen Referenzpunkte: <code>ExecutionTime</code> (für Runnables und Tasks auf Cores), <code>LatencyConstraint</code> (zwischen Triggern und Beendigung von Runnables/Tasks), <code>BlockingTime</code> (Ressourcenzugriff) sowie <code>CommunicationCycle</code> bzw. Busverzögerungen (<code>TransmissionTime</code> für PDUs und Frames). Entwickler müssen konsistente Mappings von Runnables zu Tasks, Tasks/Interrupts zu Cores sowie PDUs zu Frames definieren, um deterministische Latenzanalysen (End-to-End Timing Analysis) zu ermöglichen.</p>"}], "trans": [{"from": "FIG-0e28f34091c0f70e", "to": "FIG-8374ab7f220ca880", "fr": "R21-11", "tr": "R22-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
